const $ = selector => document.querySelector(selector);
const app = $('#app');
const esc = value => String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[ch]));
const money = cents => '$'+(Number(cents||0)/100).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
const categorySlug = s => s.toLowerCase().replace(/&/g,'').replace(/[^a-z0-9]+/g,'-').replace(/-$/,'');
let csrf = null, adminData = null, importPayload = null, importReview = null, imageBlobUrls = [];
let cart = JSON.parse(localStorage.getItem('commercedesk_cart') || '{}');
const categories=['Glass Door Hardware','Seals & Gaskets','Installation Tools','Glazing Supplies'];
function saveCart(){localStorage.setItem('commercedesk_cart',JSON.stringify(cart));updateCartCount()}
function updateCartCount(){const el=$('#cart-count');if(el)el.textContent=Object.values(cart).reduce((a,b)=>a+Number(b||0),0)}
function notify(text){const t=$('#toast');t.textContent=text;t.classList.add('active');clearTimeout(notify.timer);notify.timer=setTimeout(()=>t.classList.remove('active'),3300)}
async function api(url,{method='GET',body=null}={}){
  const headers={};if(body!==null)headers['Content-Type']='application/json';if(csrf&&method!=='GET')headers['X-CSRF-Token']=csrf;
  const r=await fetch(url,{method,headers,credentials:'same-origin',body:body!==null?JSON.stringify(body):undefined});
  const isJson=(r.headers.get('Content-Type')||'').includes('application/json');const data=isJson?await r.json():{};
  if(!r.ok){const err=new Error(data.error||'Request failed');err.errors=data.errors||{};err.status=r.status;throw err}return data;
}
function formErrors(err, container=document){
  container.querySelectorAll('.field-error').forEach(x=>x.textContent='');container.querySelectorAll('.invalid').forEach(x=>x.classList.remove('invalid'));
  for(const [field,message] of Object.entries(err.errors||{})){
    const hint=container.querySelector(`[data-field-error="${CSS.escape(field)}"]`);if(hint)hint.textContent=message;
    const input=container.querySelector(`[name="${CSS.escape(field)}"]`);if(input)input.classList.add('invalid');
  }
  const errors=Object.values(err.errors||{});
  const banner=container.querySelector('[data-form-error]');if(banner){banner.textContent=errors.length?errors.join(' · '):err.message;banner.hidden=false}
  if(!errors.length)notify(err.message)
}
function productCard(p){return `<article class="product-card"><a href="/product/${encodeURIComponent(p.slug)}"><img src="${esc(p.image_url)}" alt="${esc(p.name)}" loading="lazy"></a><div class="product-content"><span class="eyebrow">${esc(p.category)}</span><h3><a href="/product/${encodeURIComponent(p.slug)}">${esc(p.name)}</a></h3><span class="sku">SKU ${esc(p.sku)}</span><div class="price">${money(p.price_cents)}</div><span class="stock ${p.stock?'':'out'}">${p.stock?`${p.stock} in stock`:'Out of stock'}</span><button class="btn btn-primary btn-sm" data-add="${esc(p.sku)}" ${p.stock?'':'disabled'}>${p.stock?'Add to cart':'Unavailable'}</button></div></article>`}
function breadcrumbs(...parts){return `<div class="breadcrumb"><a href="/">Home</a> ${parts.map(([name,link])=>`/ ${link?`<a href="${esc(link)}">${esc(name)}</a>`:esc(name)}`).join(' ')}</div>`}
async function catalog(){return (await api('/api/catalog')).products}
