async function shop(){
 const params=new URLSearchParams(location.search);let cat=null;
 if(location.pathname.startsWith('/category/'))cat=categories.find(x=>categorySlug(x)===location.pathname.split('/').pop())||null;
 const q=params.get('q')||'';let items=await catalog();
 if(cat)items=items.filter(p=>p.category===cat);
 if(q)items=items.filter(p=>(p.name+' '+p.sku+' '+p.category+' '+p.description).toLowerCase().includes(q.toLowerCase()));
 const sort=params.get('sort')||'featured';
 if(sort==='price_low')items.sort((a,b)=>a.price_cents-b.price_cents);
 if(sort==='price_high')items.sort((a,b)=>b.price_cents-a.price_cents);
 if(sort==='name')items.sort((a,b)=>a.name.localeCompare(b.name));
 app.innerHTML=`${breadcrumbs([cat||'Shop',null])}<div class="shop-layout"><aside class="sidebar"><h3>PRODUCT CATEGORIES</h3><a href="/shop/products" class="${cat?'':'active'}">All products</a>${categories.map(c=>`<a class="${cat===c?'active':''}" href="/category/${categorySlug(c)}">${esc(c)}</a>`).join('')}</aside><section><div class="split-head"><div><span class="eyebrow">Shop our catalog</span><h1>${esc(q?'Search results':cat||'All products')}</h1>${q?`<p class="muted">Search: “${esc(q)}”</p>`:''}</div></div><div class="shop-toolbar"><span class="small muted">${items.length} product${items.length===1?'':'s'} found</span><label class="small">Sort by <select id="shop-sort"><option value="featured" ${sort==='featured'?'selected':''}>Featured</option><option value="name" ${sort==='name'?'selected':''}>Name</option><option value="price_low" ${sort==='price_low'?'selected':''}>Price: low to high</option><option value="price_high" ${sort==='price_high'?'selected':''}>Price: high to low</option></select></label></div>${items.length?`<div class="product-grid">${items.map(productCard).join('')}</div>`:'<div class="empty">No products match these filters. Try another category or search.</div>'}</section></div>`;
 $('#shop-sort').addEventListener('change',e=>{const u=new URL(location.href);u.searchParams.set('sort',e.target.value);location.assign(u.pathname+u.search)});
}
