function productFormFields(p){return `<div class="form-grid"><div class="field"><label for="p-sku">SKU *</label><input id="p-sku" name="sku" value="${esc(p?.sku||'')}" maxlength="24" ${p?'readonly':''} placeholder="GH-205" required><div class="field-error" data-field-error="sku"></div></div><div class="field"><label for="p-name">Product name *</label><input id="p-name" name="name" value="${esc(p?.name||'')}" maxlength="130" required><div class="field-error" data-field-error="name"></div></div><div class="field"><label for="p-cat">Category *</label><select id="p-cat" name="category" required><option value="">Select category</option>${categories.map(c=>`<option ${p?.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select><div class="field-error" data-field-error="category"></div></div><div class="field"><label for="p-price">Selling price ($) *</label><input id="p-price" name="price" type="number" step="0.01" min="0.01" value="${p?p.price:''}" required><div class="field-error" data-field-error="price"></div></div><div class="field"><label for="p-stock">Available inventory *</label><input id="p-stock" name="stock" type="number" step="1" min="0" value="${p?p.stock:''}" required><div class="field-error" data-field-error="stock"></div></div><div class="field"><label for="p-status">Publishing status</label><select id="p-status" name="status"><option value="draft" ${!p||p.status==='draft'?'selected':''}>Draft — hidden from storefront</option><option value="published" ${p?.status==='published'?'selected':''}>Published — visible in storefront</option></select><div class="field-error" data-field-error="status"></div></div><div class="field"><label for="p-slu">SLU number *</label><input id="p-slu" name="slu_number" value="${esc(p?.slu_number||'')}" maxlength="60" ${p?'':'required'}><small>Exact image-matching identifier. New products require this value.</small></div><div class="field"><label for="p-image-location">Image location</label><input id="p-image-location" name="image_location" value="${esc(p?.image_location||'')}" placeholder="catalog/glass/782341.png"></div><div class="field"><label for="p-brand">Brand / manufacturer</label><input id="p-brand" name="brand" value="${esc(p?.brand||'')}"></div><div class="field"><label for="p-uom">Unit of measure</label><input id="p-uom" name="uom" value="${esc(p?.uom||'Each')}"></div><div class="field"><label for="p-warehouse">Warehouse location</label><input id="p-warehouse" name="warehouse_location" value="${esc(p?.warehouse_location||'')}"></div><div class="field"><label for="p-bin">Bin / shelf location</label><input id="p-bin" name="bin_location" value="${esc(p?.bin_location||'')}"></div><div class="field"><label for="p-weight">Shipping weight</label><input id="p-weight" name="weight" value="${esc(p?.weight||'')}"></div><div class="field"><label for="p-dimensions">Dimensions</label><input id="p-dimensions" name="dimensions" value="${esc(p?.dimensions||'')}"></div><div class="field"><label for="p-reorder">Reorder level</label><input id="p-reorder" name="reorder_level" value="${esc(p?.reorder_level||'')}"></div><div class="field"><label for="p-cost">Cost price</label><input id="p-cost" name="cost_price" value="${esc(p?.cost_price||'')}"></div><div class="field full"><label for="p-description">Product description *</label><textarea id="p-description" name="description" maxlength="1800" required>${esc(p?.description||'')}</textarea><div class="field-error" data-field-error="description"></div></div><div class="field"><label for="p-image">Primary image ${p?'(optional replacement)':'*'}</label><input id="p-image" name="image" type="file" accept="image/png" ${p?'':'required'}><small>PNG filename must contain the SLU number in the filename, not as part of a longer number. Maximum 2 MB.</small><div class="field-error" data-field-error="image"></div></div><div class="field"><label>Image review</label><img id="image-preview" class="image-preview" src="${p?esc(p.image_url):'/assets/placeholder.svg'}" alt="Product image preview"><small>The PNG filename must contain the exact SLU token. Confirm the photo depicts the intended product.</small></div><label class="switch field full"><input type="checkbox" id="p-featured" ${p?.featured?'checked':''}> Feature on the store homepage</label></div>`}
