async function productEditor(){const sku=location.pathname.split('/').pop(), isNew=sku==='new';const d=await getAdminData();const p=isNew?null:d.products.find(p=>p.sku===sku);if(!isNew&&!p){adminShell('<h1>Product not found</h1><a href="/admin/products">Back</a>','products');return}adminShell(`<a class="back-link" href="/admin/products">← Product management</a><div class="eyebrow">${isNew?'New product':'Edit listing'}</div><h1>${isNew?'Add a catalog product':esc(p.name)}</h1><p class="subtitle">Save as draft for review, or publish a validated listing to the public storefront.</p><div class="help">Every new product requires an SKU, SLU number, image location, title, price, category, description and valid PNG image. Existing SKUs cannot be renamed or duplicated. Saved product changes affect the shared demo catalog.</div><form id="product-form" class="panel">${productFormFields(p)}<div class="alert danger" data-form-error hidden></div><div class="form-actions"><button type="submit" class="btn btn-primary">${isNew?'Save new product':'Save changes'}</button><a href="/admin/products" class="btn">Cancel</a>${p?.status==='published'?`<a class="btn" target="_blank" rel="noopener" href="/product/${p.slug}">View storefront listing ↗</a>`:''}</div></form>`,'products');const input=$('#p-image');input.addEventListener('change',()=>{if(input.files[0]){$('#image-preview').src=URL.createObjectURL(input.files[0])}});$('#product-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.target, fd=new FormData(form);const body={sku:fd.get('sku'),name:fd.get('name'),category:fd.get('category'),price:fd.get('price'),stock:fd.get('stock'),status:fd.get('status'),description:fd.get('description'),featured:$('#p-featured').checked,slu_number:fd.get('slu_number'),image_location:fd.get('image_location')||input.files[0]?.name||'',brand:fd.get('brand'),uom:fd.get('uom'),warehouse_location:fd.get('warehouse_location'),bin_location:fd.get('bin_location'),weight:fd.get('weight'),dimensions:fd.get('dimensions'),reorder_level:fd.get('reorder_level'),cost_price:fd.get('cost_price')};const file=input.files[0];if(file)body.image={filename:file.name,content_b64:await fileB64(file)};const btn=form.querySelector('button[type=submit]');btn.disabled=true;try{await api(isNew?'/api/admin/products':'/api/admin/products/'+encodeURIComponent(sku),{method:isNew?'POST':'PUT',body});notify('Product saved to shared catalog.');location.assign('/admin/products')}catch(err){formErrors(err,form);btn.disabled=false}})}
async function csvImport(){
 await getAdminData();
 adminShell(`<div class="eyebrow">Catalog onboarding</div><h1>Batch Import</h1><p class="subtitle">Import a distributor product catalog, validate the metadata, match every SKU to its SLU-numbered PNG and publish the batch safely.</p>
 <div class="help"><b>Required:</b> SKU, name, category, description, price, stock, status, SLU number and image location. Optional: brand, unit of measure, warehouse, bin/shelf, weight, dimensions, reorder level and cost price. Each new product must match exactly one PNG whose filename contains its SLU number in the filename, without being part of a longer number (example: IMG782341front.png).</div>
 <form id="import-form"><div class="panel"><h2>1. Spreadsheet source</h2><div class="form-grid"><div class="field"><label for="batch-file">Upload spreadsheet</label><input type="file" id="batch-file" accept=".csv,.tsv,.xlsx,.xls,text/csv"><small>CSV, TSV and XLSX · up to 8 MB · first worksheet is used. Legacy XLS requires the optional xlrd reader; convert to XLSX if unavailable.</small></div><div class="field"><label for="sheet-url">Or Google Sheets URL</label><input id="sheet-url" type="url" placeholder="https://docs.google.com/spreadsheets/d/..."><small>Link-based export requires a sheet shared for access. Private OAuth access is not enabled in this demo.</small></div><div class="field full"><label for="batch-images">Product PNG files or image folder</label><input type="file" id="batch-images" accept="image/png,.png" multiple webkitdirectory directory><small>Choose the folder containing product PNGs. Filenames must contain each product's exact SLU number. Each PNG is limited to 2 MB; combined request limit is 20 MB.</small></div></div><div class="row wrap" style="margin-top:16px"><a class="btn btn-sm" href="/samples/products-import-template.csv" download>Download full metadata template</a><a class="btn btn-sm" href="/samples/products-create.csv" download>Download populated example</a><a class="btn btn-sm" href="/samples/products-errors.csv" download>Download error example</a></div></div>
 <div class="panel"><h2>2. Validate and review</h2><p class="small muted">Preview is read-only. If any row or image fails validation, the entire batch is blocked.</p><div class="form-actions"><button class="btn btn-primary" id="import-review" type="submit">Review spreadsheet and match images</button><button class="btn btn-dark" id="import-publish" type="button" disabled>Confirm and import products</button></div><div class="alert danger" data-form-error hidden></div></div></form><div id="import-results"></div>`,'products');
 const f=$('#import-form');
 f.addEventListener('submit',async e=>{e.preventDefault();$('#import-publish').disabled=true;importPayload=null;$('#import-results').innerHTML='';try{
  const file=$('#batch-file').files[0],sheet=$('#sheet-url').value.trim();if(!file&&!sheet)throw new Error('Choose a spreadsheet file or enter a Google Sheets URL.');if(file&&sheet)throw new Error('Choose one source: file upload or Google Sheets URL.');
  const images=await Promise.all([...$('#batch-images').files].map(async x=>({filename:x.webkitRelativePath||x.name,content_b64:await fileB64(x)})));
  const payload={images};if(sheet)payload.sheet_url=sheet;else{payload.file_name=file.name;if(/\.(csv|tsv)$/i.test(file.name))payload.csv_text=await file.text();else payload.file_b64=await fileB64(file)}
  const res=await api('/api/admin/import/preview',{method:'POST',body:payload});importPayload=payload;importReview=res.review;renderImportPreview(res.review);$('#import-publish').disabled=!res.review.ready;
 }catch(err){formErrors(err,f)}});
 for(const x of ['batch-file','batch-images','sheet-url'])$('#'+x).addEventListener('change',()=>{$('#import-publish').disabled=true;importPayload=null;$('#import-results').innerHTML='';});
 $('#import-publish').addEventListener('click',async()=>{if(!importPayload||!importReview?.ready)return;$('#import-publish').disabled=true;try{const d=await api('/api/admin/import',{method:'POST',body:importPayload});$('#import-results').innerHTML=`<div class="alert success"><b>Batch imported successfully.</b> ${d.result.created} created, ${d.result.updated} updated. <a href="/shop">Open storefront →</a></div>`;notify('Batch committed.')}catch(err){formErrors(err,f);notify('The catalog may have changed. Run validation again.')}});
}
function renderImportPreview(review){const el=$('#import-results');el.innerHTML=`<div class="panel"><div class="panel-head"><h2>Import review — ${review.total} rows</h2><span class="badge ${review.ready?'published':'hold'}">${review.valid} valid / ${review.invalid} invalid</span></div>${review.image_errors.length?`<div class="alert danger">${review.image_errors.map(esc).join('<br>')}</div>`:''}<div class="table-wrap"><table class="data-table import-table"><thead><tr><th>Row</th><th>SKU / Product</th><th>SLU</th><th>Action</th><th>Image</th><th>Validation result</th></tr></thead><tbody>${review.rows.map(r=>{const local=[...$('#batch-images').files].find(f=>(f.webkitRelativePath||f.name).split('/').pop().toLowerCase()===(r.image_filename||'').toLowerCase());const image=local?URL.createObjectURL(local):null;if(image)imageBlobUrls.push(image);return `<tr><td>${r.row}</td><td><b>${esc(r.sku)}</b><br><span class="tiny muted">${esc(r.name)}</span></td><td>${esc(r.slu_number||'—')}</td><td>${esc(r.action)}</td><td>${image?`<img src="${image}" class="mini-pic" alt="Preview ${esc(r.sku)}">`:'—'}</td><td>${Object.keys(r.errors).length?`<span class="badge hold">Needs correction</span><ul>${Object.entries(r.errors).map(([k,v])=>`<li><b>${esc(k)}</b>: ${esc(v)}</li>`).join('')}</ul>`:'<span class="badge published">Ready</span>'}</td></tr>`}).join('')}</tbody></table></div><p class="small muted">${review.ready?'All records passed server validation. Click Publish validated batch to commit atomically.':'No products will be changed until all errors are corrected and the batch is reviewed again.'}</p></div>`}
async function ordersAdmin(){const d=await getAdminData();adminShell(`<div class="eyebrow">Order operations · Shipping included</div><h1>Order management</h1><p class="subtitle">Review stock reservations, handle shortages, and prepare fictional shipping labels.</p><div class="help">Orders only proceed to sample label generation after all item quantities are reserved. Held orders generate an internal purchasing alert and cannot be labeled.</div><div class="order-list">${d.orders.map(o=>`<article class="card order-card"><div class="row between"><h3>${esc(o.id)}</h3>${badgeStatus(o.status)}</div><p>${esc(o.buyer)} · ${esc(o.city)}</p><div class="order-lines">${o.items.map(x=>`<div class="order-line"><span>${esc(x.sku)} · Qty ${x.qty}</span><b>${money(x.unit_cents*x.qty)}</b></div>`).join('')}</div><div class="row between" style="margin-top:16px"><b>${money(o.total_cents)}</b><a class="btn btn-sm" href="/admin/orders/${encodeURIComponent(o.id)}">Process order →</a></div></article>`).join('')}</div>`,'orders')}
async function orderDetails(){const id=location.pathname.split('/').pop();const d=await getAdminData(),o=d.orders.find(o=>o.id===id);if(!o){adminShell('<h1>Order not found</h1>','orders');return}const statusHelp=o.status==='hold'?'Insufficient stock. Purchasing has been notified internally. Label generation is blocked.':o.status==='ready'?'All items have been reserved; ready to generate a sample shipping label.':o.status==='label_created'?'Sample label is ready for printing and warehouse handoff.':'This sample shipment has been marked dispatched.';adminShell(`<a href="/admin/orders" class="back-link">← All orders</a><div class="split-head"><div><div class="eyebrow">Order processing</div><h1>${esc(o.id)}</h1><p class="subtitle">${esc(o.buyer)} · ${esc(o.city)} · ${esc(o.created_at)}</p></div>${badgeStatus(o.status)}</div><div class="alert ${o.status==='hold'?'danger':'success'}">${statusHelp}</div><div class="panel"><h2>Items & inventory</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>SKU</th><th>Ordered quantity</th><th>Price per unit</th><th>Current available stock</th></tr></thead><tbody>${o.items.map(x=>{const p=d.products.find(p=>p.sku===x.sku);return `<tr><td>${esc(x.sku)}<br><span class="tiny muted">${esc(p?.name||'')}</span></td><td>${x.qty}</td><td>${money(x.unit_cents)}</td><td>${p?.stock??'—'}</td></tr>`}).join('')}</tbody></table></div><p class="small muted">For ready orders, stock has already been reserved and deducted from available inventory. The current stock values are remaining available-to-promise quantities.</p></div>${o.status==='hold'?`<div class="panel"><h2>Inventory shortage</h2>${Object.entries(o.shortages).map(([sku,qty])=>`<div class="alert danger">${esc(sku)}: ${qty} additional unit(s) required.</div>`).join('')}<p class="small muted">In this demo, purchasing notifications appear in the admin overview. To demonstrate replenishment, update inventory in Product Management and then recheck this order.</p><button class="btn btn-primary" id="order-recheck">Recheck inventory and reserve</button> <a class="btn" href="/admin/products">Update stock</a></div>`:''}${o.status==='ready'?`<div class="panel"><h2>Shipping</h2><p class="small muted">All lines are reserved. Generate a demonstration-only label. No real carrier API is called.</p><button class="btn btn-primary" id="order-label">Generate sample shipping label</button></div>`:''}${['label_created','shipped'].includes(o.status)?`<div class="panel"><h2>Sample shipping label</h2><div class="label-sheet" id="printable-label"><div class="label-warning">DEMO · NOT VALID FOR SHIPMENT</div><h3>CommerceDesk Supply</h3><p>REFERENCE: ${esc(o.label_ref)}</p><p>ORDER: ${esc(o.id)}</p><hr><p>TO: ${esc(o.buyer)}<br>LOCATION: ${esc(o.city)}</p><hr>${o.items.map(x=>`<p>SKU ${esc(x.sku)} · QTY ${x.qty}</p>`).join('')}<p>NO CARRIER · NO TRACKING · NO POSTAGE</p></div><button class="btn" id="order-print">Print sample label</button>${o.status==='label_created'?`<div class="info-strip" style="margin-top:18px"><h3>Warehouse label-to-order check</h3><p>Enter the label reference printed above. A wrong label cannot be accepted or dispatched.</p><div class="row wrap"><input id="verify-label-input" aria-label="Label reference to verify" placeholder="Enter SAMPLE-... reference" style="min-width:235px;border:1px solid #bfcde0;border-radius:6px;padding:10px"><button class="btn" id="order-verify">Verify label against order</button></div>${o.label_verified?'<p class="stock">✓ Label matched to order.</p>':'<p class="small muted">Not verified — warehouse handoff disabled.</p>'}</div><button class="btn btn-primary" id="order-dispatch" ${o.label_verified?'':'disabled'}>Mark sample order dispatched</button>`:''}</div>`:''}`,'orders');for(const [control,action] of [['order-recheck','recheck'],['order-label','label'],['order-verify','verify'],['order-dispatch','dispatch']]){const el=$('#'+control);if(el)el.addEventListener('click',async()=>{el.disabled=true;try{await api(`/api/admin/orders/${encodeURIComponent(id)}/${action}`,{method:'POST',body:action==='verify'?{label_ref:$('#verify-label-input').value}:{}});location.reload()}catch(err){notify(Object.values(err.errors||{}).join(' · ')||err.message);el.disabled=false}})}if($('#order-print'))$('#order-print').addEventListener('click',()=>window.print())}

function integrationsPage(){
 const groups=[['Communication & documents',['Gmail','Google Drive','Outlook','WhatsApp Business','SMS / messaging']],['Accounting & finance',['Intuit / QuickBooks','Banking APIs','Credit card processors','Payment gateways']],['Shipping & logistics',['UPS','FedEx','USPS','LTL freight','Company fleet / route systems']],['AI & intelligent assistance',['OpenAI / ChatGPT API','Google Gemini API','Document extraction','Product data enrichment']],['CRM & customer systems',['Salesforce','HubSpot','Customer portals','Supplier portals']],['Warehouse & enterprise',['ERP systems','WMS platforms','Barcode scanners','Label printers','Inventory systems']],['Data & productivity',['Excel','Google Sheets','CSV / TSV','Reporting / BI']],['Marketing & social',['Facebook','Instagram','LinkedIn','Lead capture']]];
 const workflows=[['Order intake','Gmail / WhatsApp → CommerceDesk','Capture inquiries and convert them into structured customer orders.'],['Catalog onboarding','Excel / Google Sheets → Batch Import','Load product data and match every SKU to its SLU-numbered PNG.'],['Accounting','CommerceDesk → QuickBooks','Synchronize customer, order and invoice information.'],['Fulfillment','CommerceDesk → UPS / FedEx / freight','Request rates, create carrier labels and receive tracking events.'],['Customer updates','Order events → Email / SMS / WhatsApp','Send order confirmation, dispatch and delivery updates.'],['AI assistance','Customer request / supplier file → AI API','Extract structured details and assist staff review.']];
 adminShell(`<div class="eyebrow">Connected business ecosystem</div><h1>Integrations</h1><p class="subtitle">Connect the systems a distributor already uses instead of forcing a wholesale replacement.</p><div class="integration-hero"><div><span class="eyebrow">One connected operation</span><h2>Keep your tools. Connect your workflows.</h2><p>Illustrative integration directory for orders, catalog, finance, warehouse and delivery.</p></div><div class="integration-hub"><b>CommerceDesk</b><span>Orders · Products · Inventory</span></div></div><h2 class="section-spacer">Integration directory</h2><p class="small muted">These are capability examples, not vendor partnerships or live connections.</p><div class="integration-grid">${groups.map(([name,items])=>`<article class="panel"><h3>${esc(name)}</h3><div class="integration-chips">${items.map(x=>`<span class="integration-chip">${esc(x)}</span>`).join('')}</div><span class="badge hold">Available to integrate / concept</span></article>`).join('')}</div><h2 class="section-spacer">Example business workflows</h2><div class="integration-grid">${workflows.map(([name,flow,desc])=>`<article class="panel"><span class="eyebrow">Workflow example</span><h3>${esc(name)}</h3><p class="integration-flow">${esc(flow)}</p><p class="small muted">${esc(desc)}</p><span class="badge hold">Illustrative — not live</span></article>`).join('')}</div><div class="info-strip"><h3>Need to connect your existing systems?</h3><p>Discuss your current tools, API access and operational workflow with SachinTechPro.</p><a class="btn btn-primary" href="https://sachintechpro.github.io/?project=commercedesk#contact" target="_blank" rel="noopener noreferrer">Contact SachinTechPro ↗</a></div><div class="row wrap section-spacer"><a class="btn" href="/admin/how-to">How to use this app</a><a class="btn" href="/admin/about">About CommerceDesk</a></div>`,'integrations');
}
function howToPage(){
 const steps=[['Browse the storefront','Open View front, browse categories, search for a product and open its SKU detail page.'],['Create a customer order','Add products to cart and place a fictional demo order. No real payment or address is collected.'],['Review order operations','Open Order Management. Review order lines, reserved inventory and shortage holds.'],['Manage catalog products','Use Product Management to add or edit products. Use Batch Import for spreadsheet-based catalog onboarding.'],['Prepare sample dispatch','For a ready order, generate the marked sample label, verify its reference and complete simulated dispatch.'],['Explore integration options','Open Integrations to see how email, accounting, shipping, AI and warehouse systems could connect.']];
 adminShell(`<div class="eyebrow">Guided product walkthrough</div><h1>How to use CommerceDesk</h1><p class="subtitle">A short walkthrough of the distributor order-to-fulfillment experience.</p><div class="guide-steps">${steps.map(([title,desc],i)=>`<article class="panel guide-step"><span class="guide-number">${i+1}</span><div><h3>${esc(title)}</h3><p class="small muted">${esc(desc)}</p></div></article>`).join('')}</div><div class="info-strip"><h3>Want to see your workflow represented?</h3><p>Tell us how orders, inventory, warehouse tasks and shipping work in your operation.</p><a class="btn btn-primary" href="https://sachintechpro.github.io/?project=commercedesk#contact" target="_blank" rel="noopener noreferrer">Contact SachinTechPro ↗</a></div><div class="row wrap"><a class="btn" href="/admin/integrations">Explore integrations</a><a class="btn" href="/admin/about">About CommerceDesk</a><a class="btn" href="/">View front</a></div>`,'dashboard');
}
function aboutPage(){
 adminShell(`<div class="eyebrow">About the demonstration</div><h1>CommerceDesk</h1><p class="subtitle">A B2B commerce and product-operations demonstration for distributors and wholesalers.</p><div class="panel"><h2>What it demonstrates</h2><p>CommerceDesk connects a product catalog and customer storefront with inventory-aware order creation, product administration, bulk catalog onboarding and sample fulfillment operations.</p><p>It helps distributors discuss how their own order, inventory and dispatch processes might be streamlined.</p></div><div class="panel"><h2>Who it is for</h2><p>Glass and glazing suppliers, building-material distributors, hardware wholesalers and other businesses managing product SKUs, stock and customer orders.</p></div><div class="panel"><h2>What is working vs illustrative?</h2><ul><li>Working: shared SQLite catalog, order records, server-side validation, stock reservation and transactional batch import.</li><li>Working: admin order processing and sample label verification.</li><li>Illustrative: payment, carrier labels, postage, tracking, supplier messages and external integrations are not live.</li></ul></div><div class="info-strip"><h3>We can tailor the workflow to your business.</h3><p>Built by SachinTechPro.</p><a class="btn btn-primary" href="https://sachintechpro.github.io/?project=commercedesk#contact" target="_blank" rel="noopener noreferrer">Contact SachinTechPro ↗</a></div>`,'dashboard');
}


function howToPublicPage(){
 app.innerHTML=`<div class="eyebrow">Guided demonstration</div><h1>How to use CommerceDesk</h1><p class="subtitle">A short, guided view of a distributor's product, order and fulfillment workflow.</p><div class="guide-steps"><article class="panel guide-step"><span class="guide-number">1</span><div><h3>Browse the catalog</h3><p class="small muted">Search products, browse categories and inspect SKU-level product details.</p></div></article><article class="panel guide-step"><span class="guide-number">2</span><div><h3>Place a sample order</h3><p class="small muted">Add products to the cart and complete fictional checkout. No real payment details are collected.</p></div></article><article class="panel guide-step"><span class="guide-number">3</span><div><h3>Review inventory and order status</h3><p class="small muted">The admin order queue shows ready orders, stock reservations and shortage holds.</p></div></article><article class="panel guide-step"><span class="guide-number">4</span><div><h3>Manage products and bulk imports</h3><p class="small muted">Create products or import spreadsheet catalogs with SKU, SLU, image and warehouse metadata validation.</p></div></article><article class="panel guide-step"><span class="guide-number">5</span><div><h3>Prepare a sample dispatch</h3><p class="small muted">Generate a clearly marked demonstration label, verify the order reference and complete the simulated dispatch step.</p></div></article><article class="panel guide-step"><span class="guide-number">6</span><div><h3>Explore integrations</h3><p class="small muted">See how existing email, accounting, shipping, AI, CRM and warehouse systems could be connected.</p></div></article></div><div class="info-strip"><h3>Let's map this to your operation.</h3><p>Tell us how orders, inventory, warehouse tasks and shipping work today. We can discuss a practical integration approach around your existing systems.</p><a class="btn btn-primary" href="https://sachintechpro.github.io/?project=commercedesk#contact" target="_blank" rel="noopener noreferrer">Contact SachinTechPro ↗</a></div><div class="row wrap"><a class="btn" href="/shop">Browse products</a><a class="btn" href="/admin">Open admin demo</a><a class="btn" href="/about">About CommerceDesk</a></div>`;
}
function aboutPublicPage(){
 app.innerHTML=`<div class="eyebrow">About this demonstration</div><h1>CommerceDesk</h1><p class="subtitle">A B2B commerce and product-operations demonstration for distributors and wholesalers.</p><div class="panel"><h2>What it demonstrates</h2><p>A product catalog and storefront connected to inventory-aware order creation, product administration, spreadsheet-based catalog onboarding and sample fulfillment operations.</p></div><div class="panel"><h2>Who it is for</h2><p>Glass and glazing suppliers, building-material distributors, hardware wholesalers and other businesses managing product SKUs, stock and customer orders.</p></div><div class="panel"><h2>Working capabilities and boundaries</h2><p>Product and order records, server-side validation, stock reservation, batch import review and simulated order processing are implemented in this demo. Payment processing, carrier postage, live tracking, supplier messaging and external integrations are illustrative and not connected.</p></div><div class="info-strip"><h3>Built by SachinTechPro</h3><p>Explore how a workflow can be adapted to your business and connected to the systems you already use.</p><a class="btn btn-primary" href="https://sachintechpro.github.io/?project=commercedesk#contact" target="_blank" rel="noopener noreferrer">Contact SachinTechPro ↗</a></div>`;
}

async function main(){updateCartCount();const path=location.pathname.replace(/\/$/,'')||'/';document.body.classList.toggle('marketing-home',path==='/');try{if(path==='/')await home();else if(path==='/how-to')howToPublicPage();else if(path==='/about')aboutPublicPage();else if(path==='/shop')await storefrontHome();else if(path==='/shop/products'||path.startsWith('/category/'))await shop();else if(path.startsWith('/product/'))await productPage();else if(path==='/cart')await cartPage();else if(path==='/checkout')await checkout();else if(path==='/confirmation')confirmation();else if(path==='/admin/login')login();else if(path.startsWith('/admin')){if(!await checkAdmin()){login();return}if(path==='/admin')await dashboard();else if(path==='/admin/products')await productsAdmin();else if(path==='/admin/integrations')integrationsPage();else if(path==='/admin/how-to')howToPage();else if(path==='/admin/about')aboutPage();else if(path.startsWith('/admin/products/'))await productEditor();else if(path==='/admin/import')await csvImport();else if(path==='/admin/orders')await ordersAdmin();else if(path.startsWith('/admin/orders/'))await orderDetails();else await dashboard()}else app.innerHTML='<div class="error-page"><h1>Page not found</h1><a class="btn" href="/">Home</a></div>'}catch(err){app.innerHTML=`<div class="error-page"><h1>Unable to load this page</h1><p class="muted">${esc(err.message)}</p><a href="/" class="btn">Go home</a></div>`;console.error(err)}}
document.addEventListener('click',e=>{const add=e.target.closest('[data-add]');if(add){const sku=add.dataset.add;const qty=Number($('#detail-qty')?.value||1);if(!Number.isInteger(qty)||qty<1||qty>99){notify('Choose a quantity between 1 and 99.');return}cart[sku]=(cart[sku]||0)+qty;saveCart();notify(`${sku} added to cart.`)}const remove=e.target.closest('[data-remove]');if(remove){delete cart[remove.dataset.remove];saveCart();cartPage()}});
document.addEventListener('change',e=>{const target=e.target.closest('[data-cartqty]');if(target){const qty=Number(target.value);if(!Number.isInteger(qty)||qty<1||qty>99){notify('Quantity must be 1–99.');target.value=cart[target.dataset.cartqty];return}cart[target.dataset.cartqty]=qty;saveCart();cartPage()}});
main();
